export function SfGlyph({ name, size = 16, className }: { name: string; size?: number; className?: string }) {
  const g = SF_PATHS[name];
  if (!g) return null;
  return (
    <svg viewBox="0 0 16 16" width={size} height={size} fill="currentColor" aria-hidden="true" className={className}>
      <path d={g.d} fillRule={g.evenodd ? "evenodd" : "nonzero"} />
    </svg>
  );
}
